<script setup lang="ts">
import type { Tool } from '../../../shared/types'
const {data}=await useFetch<{tools:Tool[]}>('/api/tools')
const search=ref(''),filter=ref('Todas')
const idea=reactive({title:'',description:'',role:''}),ideaError=ref(''),ideaSuccess=ref(''),sending=ref(false)
async function sendIdea(){ideaError.value='';ideaSuccess.value='';sending.value=true;try{await $fetch('/api/ideas',{method:'POST',body:{...idea}});ideaSuccess.value='Sugestão recebida!';idea.title='';idea.description='';idea.role=''}catch(e){ideaError.value=apiMessage(e)}finally{sending.value=false}}
const tools=computed(()=>data.value?.tools || [])
const categories=computed(()=>['Todas',...new Set(tools.value.map(x=>x.category))])
const results=computed(()=>tools.value.filter(x=>(filter.value==='Todas'||x.category===filter.value)&&`${x.name} ${x.description}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><div class="container page"><header class="page-heading"><div class="eyebrow">Webee Tools</div><h1>Ferramentas para simplificar</h1><p>Encontre utilitários de validação, produtividade e atendimento. A maioria funciona sem login.</p></header><div class="search-row"><input class="search-input" v-model="search" type="search" placeholder="Pesquisar ferramenta..."><div class="filters"><button v-for="c in categories" :key="c" :class="['filter-chip',{active:filter===c}]" @click="filter=c">{{c}}</button></div></div><div v-if="results.length" class="tool-grid"><ToolCard v-for="tool in results" :tool="tool" :key="tool.id"/></div><div v-else class="empty">Nenhuma ferramenta encontrada.</div><div class="panel panel-pad mt-10 max-w-[750px]"><div class="eyebrow">Participe</div><h2 class="text-[23px]">Sentiu falta de alguma ferramenta?</h2><p class="muted text-[13px]">Envie uma sugestão para orientar o crescimento das Webee Tools.</p><form class="form-grid" @submit.prevent="sendIdea"><div class="field full"><label for="idea-title">Nome da ideia</label><input id="idea-title" v-model="idea.title" required maxlength="100"></div><div class="field full"><label for="idea-description">Como ela ajudaria?</label><textarea id="idea-description" v-model="idea.description" required maxlength="800" rows="3"/></div><div class="field"><label for="idea-role">Equipe / área (opcional)</label><input id="idea-role" v-model="idea.role" maxlength="100"></div><div class="full"><div v-if="ideaError" class="error">{{ideaError}}</div><div v-if="ideaSuccess" class="success">{{ideaSuccess}}</div><button class="btn btn-primary" type="submit" :disabled="sending">{{sending?'Enviando...':'Enviar sugestão →'}}</button></div></form></div></div></template>
